import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_REPARACION, MODELO_TALLER, TABLA_REPARACIONES } from '../../models/taller-reparacion.model.mjs';

export async function buscarTallerRepository(tallerId) {
  const { Item } = await MODELO_TALLER.build(GetItemCommand)
    .key({ tallerId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarTallerRepository(tallerId, minimo) {
  const { Items = [] } = await TABLA_REPARACIONES.build(QueryCommand)
    .entities(MODELO_REPARACION)
    .query({ index: 'PorTaller', partition: tallerId })
    .options({ filters: { Reparacion: { attr: 'costeCentimos', gte: minimo } } })
    .send();
  return Items;
}
